import React from 'react';
import { Link } from 'react-router-dom';
import { 
  LayoutDashboard, 
  Users, 
  ShoppingBag, 
  CreditCard, 
  BarChart3, 
  MessageSquare, 
  Settings, 
  LogOut, 
  User, 
  Shield,
  TrendingUp,
  Package,
  Bell,
  FileText,
  PieChart,
  Home,
  Mail,
  Calendar,
  ShieldCheck,
  Key,
  Wallet,
  Truck,
  Database,
  Server,
  Cpu,
  Wifi,
  Battery,
  Smartphone,
  Tablet,
  Monitor,
  Heart,
  ShoppingCart
} from 'lucide-react';
import Badge from '../Common/Badge';

const Sidebar = ({ sidebarOpen, location, onLogout }) => {
  const userEmail = localStorage.getItem('userEmail') || 'enzo@gmail.com';

  const navItems = [
    { 
      to: "/dashboard", 
      icon: <LayoutDashboard className="h-5 w-5" />, 
      label: "Tableau de bord", 
      exact: true 
    },
    { 
      to: "/dashboard/users", 
      icon: <Users className="h-5 w-5" />, 
      label: "Utilisateurs", 
      badge: "42", 
      badgeColor: "accent" 
    },
    { 
      to: "/dashboard/products", 
      icon: <ShoppingBag className="h-5 w-5" />, 
      label: "Produits", 
      badge: "156", 
      badgeColor: "secondary" 
    },
    { 
      to: "/dashboard/orders", 
      icon: <CreditCard className="h-5 w-5" />, 
      label: "Commandes", 
      badge: "24", 
      badgeColor: "primary" 
    },
    { 
      to: "/dashboard/analytics", 
      icon: <BarChart3 className="h-5 w-5" />, 
      label: "Analytique" 
    },
    { 
      to: "/dashboard/messages", 
      icon: <MessageSquare className="h-5 w-5" />, 
      label: "Messages", 
      badge: "3", 
      badgeColor: "accent" 
    },
    { 
      to: "/dashboard/settings", 
      icon: <Settings className="h-5 w-5" />, 
      label: "Paramètres" 
    },
  ];

  // ... reste du code identique ...

  return (
    <aside className={`fixed inset-y-0 left-0 z-50 w-64 bg-white/95 dark:bg-neutral-900/95 backdrop-blur-xl border-r border-neutral-200/50 dark:border-neutral-800/50 transform transition-transform duration-300 ${sidebarOpen ? 'translate-x-0' : '-translate-x-full'} lg:translate-x-0`}>
      <div className="flex flex-col h-full sidebar-scrollbar sidebar-depth">
        {/* ... reste du code ... */}

        {/* Navigation principale */}
        <nav className="flex-1 p-4 overflow-y-auto">
          <div className="mb-6">
            <h3 className="text-xs font-semibold text-neutral-500 dark:text-neutral-400 uppercase tracking-wider mb-3 px-3">
              Navigation
            </h3>
            <ul className="space-y-1">
              {navItems.map((item) => {
                const isActive = item.exact 
                  ? location.pathname === item.to
                  : location.pathname.startsWith(item.to);

                return (
                  <li key={item.to}>
                    <Link 
                      to={item.to} 
                      className={`sidebar-item flex items-center space-x-3 px-4 py-3 rounded-xl ${isActive ? 'bg-gradient-to-r from-primary-500 to-primary-600 text-white font-medium shadow-lg shadow-primary-500/20' : 'text-neutral-700 dark:text-neutral-300 hover:bg-neutral-100 dark:hover:bg-neutral-800/50 transition-colors'}`}
                    >
                      <div className={`${isActive ? 'text-white' : 'text-neutral-500 dark:text-neutral-400'}`}>
                        {item.icon}
                      </div>
                      <span className="flex-1">{item.label}</span>
                      {item.badge && (
                        <Badge 
                          color={item.badgeColor} 
                          size="sm"
                          className={`ml-auto ${isActive ? 'bg-white/20 hover:bg-white/30' : ''}`}
                        >
                          {item.badge}
                        </Badge>
                      )}
                    </Link>
                  </li>
                );
              })}
            </ul>
          </div>

          {/* ... reste du code ... */}
        </nav>

        {/* ... reste du code ... */}
      </div>
    </aside>
  );
};

export default Sidebar;
